                <AnimatePresence>
                  {expanded === i && (
                    <motion.div
                      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                      style={{ color: 'rgba(255,255,255,0.9)', fontSize: 13, marginTop: 8 }}
                    >
                      Expanded content for item {i + 1}. Layout animation handles the resize smoothly!
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            ))}
          </div>
        </DemoCard>
