  const [speed, setSpeed] = useState(2)

  return (
    <div>
      <SectionHeader
        icon={<Zap size={20} />}
        title="CSS Custom Properties (Variables)"
        subtitle="Animating via CSS variables, @property, dynamic theming"
        color="#eab308"
      />
