            { ph: 'Email',            val: email,    set: setEmail,    secure: false, kb: 'email-address'  },
            { ph: 'Password',         val: password, set: setPassword, secure: true,  kb: 'default'        },
            { ph: 'Confirm password', val: confirm,  set: setConfirm,  secure: true,  kb: 'default'        },
