      {open && (
        <View style={{ marginTop: 6, backgroundColor: '#161616', borderRadius: 12, borderWidth: 1, borderColor: '#ffffff14', overflow: 'hidden' }}>
          {employees.map(emp => (
            <TouchableOpacity
              key={emp.id}
