          <Text style={{ fontSize: 11, color: '#ffffffb3', fontFamily: 'monospace' }}>
            {settings.office_latitude.toFixed(5)}
          </Text>
          <Text style={{ fontSize: 11, color: '#ffffffb3', fontFamily: 'monospace' }}>
            {settings.office_longitude.toFixed(5)}
          </Text>
