    } catch {}
    finally { setClearing(false) }
  }

  // Group by event + second bucket — same logic as web
  const grouped = log.reduce((acc: Record<string, EventLogEntry[]>, entry) => {
    const key = `${entry.event_name}:${entry.created_at?.slice(0, 19)}`
    if (!acc[key]) acc[key] = []
