/* @arkzen:web:page:index */
/* @arkzen:web:page:layout:guest */

import React, { useState, useRef, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

const IndexPage = () => {
  const [sliderOpen, setSliderOpen] = useState(false)
  const [initialIndex, setInitialIndex] = useState(0)
  const [avatarVisible, setAvatarVisible] = useState(false)
  const [orbitVisible, setOrbitVisible] = useState(false)
  const [navVisible, setNavVisible] = useState(false)
  const pageRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const cleanup = lain098Animations(
      pageRef,
      () => setAvatarVisible(true),   // avatar scale-in
      () => setOrbitVisible(true),    // orbit expand
      () => setNavVisible(true),      // nav + side text
    )
    return cleanup
  }, [])

  const openSlider = (index: number) => {
    setInitialIndex(index)
    setSliderOpen(true)
  }

  // GLOBAL THEME TRANSITION UPON REACHING THE FOOTER
  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger)
    const footerEl = document.querySelector('.scrapbook-footer')
    if (!footerEl) return

    const ctx = gsap.context(() => {
      gsap.to(".lain-root", {
        backgroundColor: "#1D1812",
        color: "#f0f0f0",
        duration: 2,
        ease: "power2.inOut",
        scrollTrigger: {
          trigger: footerEl,
          start: "top bottom",
          end: "top 30%",
          scrub: 1.2
        }
      })
      gsap.to(".lain-root", {
        "--muted": "rgba(255,255,255,0.45)",
        "--border": "rgba(255,255,255,0.08)",
        "--text-light": "rgba(255,255,255,0.6)",
        duration: 2,
        ease: "power2.inOut",
        scrollTrigger: {
          trigger: footerEl,
          start: "top bottom",
          end: "top 30%",
          scrub: 1.2
        }
      })
    }, footerEl)
    return () => ctx.revert()
  }, [])

  return (
    <motion.div
      ref={pageRef}
      className="lain-root"
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
    >
      {/* ⭐ GLOBAL FIXED BLEEDING BLUE ORB STARTS HERE ⭐ */}
      <div className="global-bg-bleed" />

      <LainNav visible={navVisible} />
      <HeroSection
        onPreview={openSlider}
        orbitVisible={orbitVisible}
        avatarVisible={avatarVisible}
      />
      <IntroStrip />
      <WorksSection />
      <GalleryStrip />
      <DiscographySection />
      <CommissionsSection />
      <AboutSection />
      <ContactSection />
      <ZenSection />
      <GridSection />
      <Footer />

      <AnimatePresence>
        {sliderOpen && (
          <FullscreenSlider
            items={CAROUSEL_ITEMS}
            initialIndex={initialIndex}
            onClose={() => setSliderOpen(false)}
          />
        )}
      </AnimatePresence>
    </motion.div>
  )
}

export default IndexPage

